CREATE OR REPLACE FUNCTION public.crear_queja_publica(p_token text, p_cliente_nombre text, p_email_cliente text, p_telefono text, p_categoria text, p_descripcion text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_form formularios_publicos;
  v_folio text;
BEGIN
  SELECT * INTO v_form
  FROM formularios_publicos
  WHERE token = p_token AND activo = true
  LIMIT 1;

  IF v_form.id IS NULL THEN
    RAISE EXCEPTION 'El enlace no es válido o ya no está disponible';
  END IF;

  IF p_cliente_nombre IS NULL OR btrim(p_cliente_nombre) = '' THEN
    RAISE EXCEPTION 'El nombre del quejoso es obligatorio';
  END IF;

  v_folio := generar_folio_queja();

  INSERT INTO quejas (
    folio, cliente_nombre, email_cliente, telefono,
    categoria, descripcion, estado, fecha
  ) VALUES (
    v_folio,
    btrim(p_cliente_nombre),
    p_email_cliente,
    p_telefono,
    p_categoria,
    p_descripcion,
    'Recibido',
    now()
  );

  RETURN v_folio;
END;
$function$

CREATE OR REPLACE FUNCTION public.notificar_queja_publica(p_folio text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_queja_id uuid;
  v_categoria text;
  v_staff record;
BEGIN
  SELECT id, categoria INTO v_queja_id, v_categoria
  FROM quejas
  WHERE folio = p_folio
  LIMIT 1;

  IF v_queja_id IS NULL THEN
    RAISE EXCEPTION 'Queja no encontrada para el folio %', p_folio;
  END IF;

  -- Evitar notificaciones duplicadas si el frontend reintenta.
  IF EXISTS (
    SELECT 1 FROM public.notificaciones
    WHERE tipo = 'queja_nueva' AND origen_id = v_queja_id::text
  ) THEN
    RETURN;
  END IF;

  FOR v_staff IN
    SELECT id, email FROM public.usuarios
    WHERE rol IN ('admin', 'calidad')
      AND (estado IS NULL OR estado = 'activo')
  LOOP
    INSERT INTO public.notificaciones (usuario_id, fecha, tipo, mensaje, enlace, origen_id)
    VALUES (
      v_staff.id,
      now(),
      'queja_nueva',
      'Nueva queja ' || p_folio || ' registrada: ' || COALESCE(v_categoria, ''),
      '/quejas',
      v_queja_id::text
    );

    INSERT INTO public.mail_queue (destinatario, asunto, cuerpo, estado, intentos, created_at)
    SELECT v_staff.email, 'Nueva queja ' || p_folio, 'Se recibió una nueva queja con folio ' || p_folio || '.', 'pendiente', 0, now()
    WHERE v_staff.email IS NOT NULL;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_adjunto_queja_publica(p_queja_id uuid, p_nombre text, p_storage_path text, p_tamano bigint DEFAULT NULL::bigint, p_tipo_mime text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_adjunto_id uuid;
  v_estado     text;
BEGIN
  IF btrim(COALESCE(p_nombre, '')) = '' OR btrim(COALESCE(p_storage_path, '')) = '' THEN
    RAISE EXCEPTION 'Nombre y ruta del adjunto son obligatorios';
  END IF;

  SELECT estado INTO v_estado FROM public.quejas WHERE id = p_queja_id;
  IF v_estado IS NULL THEN
    RAISE EXCEPTION 'Queja no encontrada';
  END IF;
  IF v_estado <> 'Recibido' THEN
    RAISE EXCEPTION 'Solo se pueden adjuntar evidencias mientras la queja está en estado «Recibido»';
  END IF;

  IF (SELECT count(*) FROM public.queja_adjuntos WHERE queja_id = p_queja_id) >= 10 THEN
    RAISE EXCEPTION 'Límite de 10 evidencias por queja alcanzado';
  END IF;

  -- Mapeo explícito: p_nombre alimenta ambas columnas de nombre
  -- (legacy nombre_archivo NOT NULL + estándar nombre) y p_storage_path
  -- alimenta storage_path + url_archivo legacy
  INSERT INTO public.queja_adjuntos (
    queja_id,
    nombre,
    nombre_archivo,
    storage_path,
    url_archivo,
    tamano,
    tipo_mime,
    usuario_id,
    created_at
  ) VALUES (
    p_queja_id,
    btrim(p_nombre),
    btrim(p_nombre),
    btrim(p_storage_path),
    btrim(p_storage_path),
    COALESCE(p_tamano, 0),
    COALESCE(nullif(btrim(COALESCE(p_tipo_mime, '')), ''), 'application/octet-stream'),
    NULL,
    now()
  )
  RETURNING id INTO v_adjunto_id;

  RETURN v_adjunto_id;
END;
$function$
